package cn.mop.persistence;
import cn.mop.domain.monitoring.*;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class MonitoringBorrowedStorageTransactionTest {
 final RawMonitoringEvent event=new RawMonitoringEvent(new RawMonitoringEvent.Key(UUID.randomUUID(),"44",RawMonitoringEvent.Phase.RECOVERED),new RawMonitoringEvent.Binding(UUID.randomUUID(),UUID.randomUUID()),Instant.parse("2026-10-24T00:00:00.123456789Z"),Instant.parse("2026-10-24T00:01:00Z"),new byte[]{1,2,3});
 @Test void borrowedRawReadNeverCommitsRollsBackOrClosesOwnersTransaction()throws Exception{
  var c=mock(Connection.class);when(c.getTransactionIsolation()).thenReturn(Connection.TRANSACTION_READ_COMMITTED);var insert=mock(PreparedStatement.class);var select=mock(PreparedStatement.class);var inserted=mock(ResultSet.class);when(inserted.next()).thenReturn(false);when(insert.executeQuery()).thenReturn(inserted);var storedRow=stored(event);when(select.executeQuery()).thenReturn(storedRow);when(c.prepareStatement(startsWith("INSERT"))).thenReturn(insert);when(c.prepareStatement(startsWith("SELECT"))).thenReturn(select);
  var receipt=PostgresRawMonitoringEventRepository.storeInTransaction(c,event);assertEquals(PostgresRawMonitoringEventRepository.Outcome.SAME_CONTENT,receipt.outcome());assertEquals(event.receivedAt(),receipt.firstReceivedAt());verify(c,never()).commit();verify(c,never()).rollback();verify(c,never()).close();verify(c,never()).setAutoCommit(anyBoolean());
 }
 @Test void autoCommitAndRepeatableReadCannotPretendToJoinOwnedReadCommitted()throws Exception{for(int isolation:new int[]{Connection.TRANSACTION_READ_COMMITTED,Connection.TRANSACTION_REPEATABLE_READ}){var c=mock(Connection.class);when(c.getAutoCommit()).thenReturn(isolation==Connection.TRANSACTION_READ_COMMITTED);when(c.getTransactionIsolation()).thenReturn(isolation);assertThrows(IllegalStateException.class,()->PostgresRawMonitoringEventRepository.storeInTransaction(c,event));verify(c,never()).prepareStatement(anyString());}}
 @Test void conflictAndHoldUseTheExactSameConnectionAndDiscloseNoCanonicalId()throws Exception{var c=mock(Connection.class);UUID held=UUID.randomUUID();try(var raw=mockStatic(PostgresRawMonitoringEventRepository.class);var quarantine=mockStatic(PostgresMonitoringQuarantineRepository.class)){
  raw.when(()->PostgresRawMonitoringEventRepository.storeInTransaction(c,event)).thenReturn(new PostgresRawMonitoringEventRepository.Receipt(PostgresRawMonitoringEventRepository.Outcome.CONFLICT_REQUIRES_REVIEW,null,null));
  quarantine.when(()->PostgresMonitoringQuarantineRepository.holdInTransaction(eq(c),any())).thenAnswer(call->{var candidate=(QuarantinedMonitoringEvent)call.getArgument(1);assertEquals(event.binding().tenantId(),candidate.claims().tenantId());assertEquals(QuarantinedMonitoringEvent.Reason.SOURCE_KEY_CONFLICT,candidate.reason());assertArrayEquals(event.payload(),candidate.payload());return new PostgresMonitoringQuarantineRepository.Receipt(PostgresMonitoringQuarantineRepository.Outcome.HELD,held,event.receivedAt());});
  var result=(PostgresMonitoringEventStorageCoordinator.HeldResult)PostgresMonitoringEventStorageCoordinator.storeInTransaction(c,event);assertEquals(held,result.receipt().quarantineId());assertFalse(result.dispatchAllowed());assertFalse(result.sourceAuthorized());verifyNoInteractions(c);
 }}
 @Test void failedHoldDoesNotProduceDurableSuccess()throws Exception{var c=mock(Connection.class);try(var raw=mockStatic(PostgresRawMonitoringEventRepository.class);var quarantine=mockStatic(PostgresMonitoringQuarantineRepository.class)){
  raw.when(()->PostgresRawMonitoringEventRepository.storeInTransaction(c,event)).thenReturn(new PostgresRawMonitoringEventRepository.Receipt(PostgresRawMonitoringEventRepository.Outcome.CONFLICT_REQUIRES_REVIEW,null,null));quarantine.when(()->PostgresMonitoringQuarantineRepository.holdInTransaction(eq(c),any())).thenThrow(new SQLException("unit failure"));assertThrows(SQLException.class,()->PostgresMonitoringEventStorageCoordinator.storeInTransaction(c,event));verify(c,never()).commit();
 }}
 ResultSet stored(RawMonitoringEvent e)throws Exception{var r=mock(ResultSet.class);when(r.next()).thenReturn(true,false);when(r.getString("source_authorization_status")).thenReturn("UNVERIFIED");when(r.getString("storage_status")).thenReturn("STORED_ONLY");when(r.getString("source_event_id")).thenReturn(e.key().sourceEventId());when(r.getString("source_phase")).thenReturn(e.key().phase().name());when(r.getObject("pool_id",UUID.class)).thenReturn(e.key().poolId());when(r.getObject("tenant_id",UUID.class)).thenReturn(e.binding().tenantId());when(r.getObject("asset_id",UUID.class)).thenReturn(e.binding().assetId());when(r.getObject("id",UUID.class)).thenReturn(UUID.randomUUID());when(r.getLong("occurred_epoch_second")).thenReturn(e.occurredAt().getEpochSecond());when(r.getInt("occurred_nano")).thenReturn(e.occurredAt().getNano());when(r.getLong("received_epoch_second")).thenReturn(e.receivedAt().getEpochSecond());when(r.getInt("received_nano")).thenReturn(e.receivedAt().getNano());when(r.getBytes("payload")).thenReturn(e.payload());when(r.getString("payload_sha256")).thenReturn(e.payloadSha256());when(r.getString("content_fingerprint")).thenReturn(e.contentFingerprint());return r;}
}
